// NODE: "Clean and Prepare Text"
// Removes HTML, quoted reply history, and trims the email text
// before sending it to the AI (saves tokens and improves accuracy).

const items = $input.all();
const output = [];

for (const item of items) {
  try {
    let text = item.json.text || item.json.snippet || '';

    // Remove leftover HTML tags
    text = text.replace(/<[^>]*>/g, ' ');

    // Remove quoted blocks from previous emails (common patterns)
    text = text.split(/\n\s*(On .* wrote:|-----\s*Original Message\s*-----)/i)[0];

    // Remove lines starting with ">" (quotes)
    text = text.split('\n').filter((line) => !line.trim().startsWith('>')).join('\n');

    // Normalize excessive whitespace and line breaks
    text = text.replace(/\s{2,}/g, ' ').trim();

    // Limit size to control token cost
    const CHAR_LIMIT = 3000;
    if (text.length > CHAR_LIMIT) {
      text = text.slice(0, CHAR_LIMIT) + '...';
    }

    output.push({
      json: {
        emailId: item.json.id,
        threadId: item.json.threadId,
        sender: item.json.from?.value?.[0]?.address || item.json.from || 'unknown',
        subject: item.json.subject || '(no subject)',
        cleanText: text || '(email has no readable text content)'
      }
    });
  } catch (err) {
    output.push({
      json: {
        error: true,
        reason: `Failed to clean email: ${err.message}`,
        emailId: item.json?.id || 'unknown'
      }
    });
  }
}

return output;

// NODE: "Validate AI Response"
// The AI must return a JSON with: category, confidence, suggested_reply.
// This node guarantees that even if the AI "hallucinates" a wrong format,
// the workflow doesn't break - it falls back to a safe default.

const VALID_CATEGORIES = ['Support', 'Sales', 'Finance', 'Other'];

const items = $input.all();
const output = [];

for (const item of items) {
  const sourceData = $('Clean and Prepare Text').item.json;

  try {
    // The AI response usually comes in .content or .message.content
    let raw =
      item.json.content ||
      item.json.message?.content ||
      item.json.choices?.[0]?.message?.content ||
      item.json.text ||
      '';

    // Remove markdown fences (```json ... ```) in case the AI adds them by mistake
    raw = raw.replace(/```json|```/g, '').trim();

    const parsed = JSON.parse(raw);

    const category = VALID_CATEGORIES.includes(parsed.category)
      ? parsed.category
      : 'Other';

    const confidence =
      typeof parsed.confidence === 'number' && parsed.confidence >= 0 && parsed.confidence <= 1
        ? parsed.confidence
        : 0;

    output.push({
      json: {
        error: false,
        emailId: sourceData.emailId,
        threadId: sourceData.threadId,
        sender: sourceData.sender,
        subject: sourceData.subject,
        category,
        confidence,
        suggestedReply: parsed.suggested_reply || '',
        highConfidence: confidence >= 0.8
      }
    });
  } catch (err) {
    // Safe fallback: if the AI fails, it falls into "Other" for human review
    output.push({
      json: {
        error: true,
        reason: `Failed to parse AI response: ${err.message}`,
        emailId: sourceData.emailId,
        threadId: sourceData.threadId,
        sender: sourceData.sender,
        subject: sourceData.subject,
        category: 'Other',
        confidence: 0,
        suggestedReply: '',
        highConfidence: false
      }
    });
  }
}

return output;

